import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"The cut","description":"","frontmatter":{},"headers":[],"params":{"slug":"editing","address":"42f66550-92c6-841a-b346-e432272072b7","receipt":"8ca1c578-ee58-8336-8646-f2afa62a8e00"},"relativePath":"docs/publications/editing.md","filePath":"docs/publications/[slug].md"}`),a={name:`docs/publications/editing.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="the-cut" tabindex="-1">The cut <a class="header-anchor" href="#the-cut" aria-label="Permalink to “The cut”">​</a></h1><blockquote><p>video and film editing as decidable arithmetic, the craft a professional editor works in — timecode is a ring (at 24 fps the frame field runs 0..23 then wraps, ℤ/24), a minute is 1440 frames, NTSC drop-frame drops 2 frame-numbers a minute except every tenth (108 an hour) to hold 29.97 to the clock, 4K UHD is EXACTLY four Full-HD frames (3840×2160 = 4·1920·1080), widescreen 16:9 beats academy 4:3 by cross-multiplication (48 &gt; 36), the rule of thirds crosses at four power points in a nine-square, a crossfade makes two clips a+b−L long (inclusion–exclusion on the timeline, the same identity the compare tool folds), 48 kHz audio is 2000 samples a frame exactly in sync, and six 30° steps span the 180° axis — the arithmetic of the edit, NOT a codec, an NLE or a renderer</p></blockquote><p>These 9 facts hold by decision. Each was proven in Lean 4 — no Mathlib, checked sorry-free — and every sentence below links the proof that seals it. This note claims nothing beyond what its theorems settle: not that the domain is complete, only that the prose says nothing the proofs do not. It was written by reading the sealed ledger; read the proofs, not the prose.</p><h2 id="the-facts-each-backed-by-its-proof" tabindex="-1">The facts, each backed by its proof <a class="header-anchor" href="#the-facts-each-backed-by-its-proof" aria-label="Permalink to “The facts, each backed by its proof”">​</a></h2><ul><li>Timecode is a ring: at 24 fps the frame field runs 0..23 then wraps to the next second — (List.range 24).length = 24 ∧ 24 % 24 = 0. An editor counts frames in ℤ/24, the same close the rosette makes in ℤ/7. — <a href="/theorem/frame_index_is_z24">proof</a>.</li><li>A minute of 24 fps footage is 1440 frames: 24 · 60 = 1440 — the count a timeline cursor crosses between two minute marks. — <a href="/theorem/frames_per_minute">proof</a>.</li><li>NTSC drop-frame drops 2 frame-numbers each minute EXCEPT every tenth, so an hour drops 2 · 54 = 108 (54 of the 60 minutes are not multiples of ten) — the fudge that holds 29.97 fps to the wall clock. No frame of picture is lost, only its number. — <a href="/theorem/dropframe_per_hour">proof</a>.</li><li>A 4K UHD frame is EXACTLY four Full-HD frames: 3840 · 2160 = 4 · (1920 · 1080) — double the width, double the height, four times the pixels, which is why HD drops cleanly into a UHD timeline. — <a href="/theorem/uhd_is_four_times_hd">proof</a>.</li><li>Widescreen 16:9 is wider than academy 4:3, decided by cross-multiplication: 16 · 3 = 48 &gt; 36 = 9 · 4 — the pillarbox on a 4:3 clip in a 16:9 sequence, proven. — <a href="/theorem/widescreen_wider_than_academy">proof</a>.</li><li>The rule of thirds: two lines each way cut the frame into a nine-square and cross at four power points — 3 · 3 = 9 ∧ 2 · 2 = 4 — where the eye rests and the editor places the subject. — <a href="/theorem/rule_of_thirds_power_points">proof</a>.</li><li>A crossfade of 12 frames between two 48-frame clips runs 48 + 48 − 12 = 84: the dissolve is exactly the timeline’s inclusion–exclusion — the SAME identity uuidna_compare folds to read similarity from difference. — <a href="/theorem/crossfade_overlap">proof</a>.</li><li>48 kHz audio at 24 fps is 2000 samples a frame, and it divides evenly (48000 % 24 = 0) — the exact sync that lets a cut land on a sample, not between two. — <a href="/theorem/audio_samples_per_frame">proof</a>.</li><li>The grammar of the cut in one line: six 30° steps span the 180° axis — 30 · 6 = 180 — so a cut must turn at least 30° to avoid a jump, and the camera must stay one side of the 180° line. — <a href="/theorem/angle_of_the_cut">proof</a>.</li></ul><h2 id="provenance" tabindex="-1">Provenance <a class="header-anchor" href="#provenance" aria-label="Permalink to “Provenance”">​</a></h2><p>These 9 proofs fold, order-invariant, to the receipt <code>8ca1c578-ee58-8336-8646-f2afa62a8e00</code> — recompute it from the same ledger and it returns. The note itself content-addresses to a uuid, so any edit is visible. Writing descends from reading: this note holds only what the proofs it links already sealed, and it was audited by uuidna&#39;s own honesty gate before it was published — a sentence that overreached a proof would have been refused, not shipped.</p><p>Source · <a href="https://github.com/uuidna/uuidna/blob/main/lean/Editing.lean" target="_blank" rel="noreferrer">lean/Editing.lean</a> · <a href="/theorems">all theorems</a></p><hr><p><strong>Audited before published</strong> · this note passed uuidna&#39;s honesty gate at build time — every claim above links the proof that seals it. Content-address <code>42f66550</code> · proofs fold to receipt <code>8ca1c578</code> (the handles; the full uuids are in this page&#39;s meta, recomputable) · 9 sealed theorems.</p><p><a href="/publications">All publications</a> · <a href="/theorems">All theorems</a> · <a href="/trials">How auditing works</a></p>`,11)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};